pub mod constructor {
    const INTERNAL_ERR: &str = "`ethabi_derive` internal error";
    #[derive(Debug, Clone, PartialEq)]
    pub struct Constructor {
        pub access_control_manager: Vec<u8>,
    }
    impl Constructor {
        pub fn decode(data: &[u8]) -> Result<Self, String> {
            let mut values = ethabi::decode(&[ethabi::ParamType::Address], data.as_ref())
                .map_err(|e| format!("unable to decode constructor input: {:?}", e))?;
            values.reverse();
            Ok(Self {
                access_control_manager: values
                    .pop()
                    .expect(INTERNAL_ERR)
                    .into_address()
                    .expect(INTERNAL_ERR)
                    .as_bytes()
                    .to_vec(),
            })
        }
        pub fn encode(&self) -> Vec<u8> {
            ethabi::encode(
                &[
                    ethabi::Token::Address(
                        ethabi::Address::from_slice(&self.access_control_manager),
                    ),
                ],
            )
        }
    }
}
